// === Pengaturan ===
// ID model gambar di OpenRouter. Cek nama persisnya di openrouter.ai/models jika ada error "model not found".
const MODEL = {
  'nano-banana-pro': 'google/gemini-3-pro-image-preview', // hasil final (teks & logo paling rapi)
  'nano-banana': 'google/gemini-2.5-flash-image',         // draf cepat & murah
  'seedream': 'bytedance-seed/seedream-4.5',               // alternatif
};
const MAX_REFERENSI = 3;

const b = $input.first().json.body;
const modelKey = MODEL[b.model] ? b.model : 'nano-banana-pro';
const dim = String(b.dimensi);

// --- Rasio: A4, "4:5", atau "1080x1350" -> rasio terdekat yang didukung model ---
let w, h, label;
const r = dim.match(/(\d+(?:\.\d+)?)\s*:\s*(\d+(?:\.\d+)?)/);
const px = dim.match(/(\d{3,5})\s*[x×]\s*(\d{3,5})/);
if (/\bA4\b/i.test(dim)) {
  const land = /landscape|mendatar/i.test(dim);
  [w, h] = land ? [297, 210] : [210, 297];
  label = `A4 ${land ? 'landscape' : 'portrait'} print poster`;
} else if (r) { [w, h] = [+r[1], +r[2]]; label = `${r[1]}:${r[2]}`; }
else if (px) { [w, h] = [+px[1], +px[2]]; label = `${px[1]}x${px[2]} px`; }
else { [w, h] = [1, 1]; label = '1:1'; }
const SUPPORTED = ['1:1', '2:3', '3:2', '3:4', '4:3', '4:5', '5:4', '9:16', '16:9', '21:9'];
const aspect_ratio = SUPPORTED.reduce((best, s) => {
  const [a, c] = s.split(':').map(Number);
  const [x, y] = best.split(':').map(Number);
  return Math.abs(Math.log(a / c / (w / h))) < Math.abs(Math.log(x / y / (w / h))) ? s : best;
});

// --- Ambil gambar (logo & referensi) lalu kirim sebagai base64 ---
const helpers = this.helpers;
async function ambilGambar(link) {
  let url = String(link).trim();
  const id = url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?(?:.*&)?id=)([\w-]+)/);
  if (id) url = `https://drive.google.com/uc?export=download&id=${id[1]}`;
  const res = await helpers.httpRequest({ url, encoding: 'arraybuffer', returnFullResponse: true });
  const type = String(res.headers['content-type'] || '').split(';')[0];
  if (!type.startsWith('image/')) {
    throw new Error(`Link bukan gambar (${type || 'tanpa tipe'}): ${link}. Pastikan akses Drive "Siapa saja yang memiliki link".`);
  }
  return { type: 'image_url', image_url: { url: `data:${type};base64,${Buffer.from(res.body).toString('base64')}` } };
}

const images = [];
const catatanGambar = [];
if (b.logo_url) {
  images.push(await ambilGambar(b.logo_url));
  catatanGambar.push(`Image ${images.length} is the company LOGO. Place this exact logo, unchanged (same shape, colors and lettering, do not redraw or restyle it), ${b.posisi_logo || 'in the top-left corner'}, small but clearly visible, with enough contrast against the background.`);
}
const refs = (Array.isArray(b.referensi_gambar) ? b.referensi_gambar : []).filter(Boolean).slice(0, MAX_REFERENSI);
if (refs.length) {
  const start = images.length + 1;
  for (const link of refs) images.push(await ambilGambar(link));
  const idx = refs.length === 1 ? `Image ${start} is` : `Images ${start}-${images.length} are`;
  catatanGambar.push(`${idx} STYLE REFERENCES chosen by the client as the minimum quality standard. Match or exceed their layout quality, visual hierarchy, typography style, color treatment, lighting and level of polish. Do NOT copy their text, products, logos or brand names.`);
}

// --- Teks yang wajib dirender ---
const teks = b.teks_presisi || {};
const namaTeks = { headline: 'Headline (largest, most prominent)', subheadline: 'Subheadline', harga: 'Price badge', cta: 'Call-to-action button' };
const baris = Object.entries(teks)
  .filter(([, v]) => v !== null && v !== undefined && String(v).trim() !== '')
  .map(([k, v]) => `- ${namaTeks[k] || k}: "${String(v).trim()}"`);

const prompt = [
  `Create a professional ${b.jenis_materi} design, ${label}, aspect ratio ${aspect_ratio}, full-bleed composition filling the entire frame.`,
  ...catatanGambar,
  String(b.deskripsi_visual).trim(),
  baris.length
    ? `TEXT TO RENDER — render ONLY these texts, spelled EXACTLY as written (same capitalization, numbers and "Rp" format), sharp and highly legible, with clear hierarchy:\n${baris.join('\n')}\nDo not add any other words.`
    : `Do not render any text, letters or numbers${b.logo_url ? ' except the logo' : ''}.`,
  b.catatan_brand ? `Brand guidelines: ${b.catatan_brand}` : '',
  'Quality: award-winning commercial advertising design, appetizing, ultra detailed, crisp edges, balanced negative space, high contrast between text and background.',
  'Avoid: misspelled or garbled text, extra random text, watermark, third-party logos, cluttered layout, deformed or plastic-looking food, claims/prices/promos not listed above.',
].filter(Boolean).join('\n\n');

return [{ json: {
  issue_id: String(b.issue_id),
  model: MODEL[modelKey],
  aspect_ratio,
  jumlah_referensi: refs.length,
  pakai_logo: Boolean(b.logo_url),
  request: {
    model: MODEL[modelKey],
    modalities: ['image', 'text'],
    messages: [{ role: 'user', content: [{ type: 'text', text: prompt }, ...images] }],
    image_config: { aspect_ratio },
  },
} }];

// Ambil gambar dari respons OpenRouter (beberapa format didukung).
const r = $input.first().json;
const msg = (r.choices && r.choices[0] && r.choices[0].message) || {};
let src = (msg.images && msg.images[0] && msg.images[0].image_url && msg.images[0].image_url.url)
  || (r.data && r.data[0] && (r.data[0].b64_json || r.data[0].url));
if (!src) {
  const alasan = (r.error && r.error.message) || (typeof msg.content === 'string' && msg.content.slice(0, 300)) || 'respons model tidak berisi gambar';
  throw new Error(alasan);
}
let b64, mime = 'image/png';
const dataUrl = String(src).match(/^data:([^;]+);base64,(.+)$/s);
if (dataUrl) { mime = dataUrl[1]; b64 = dataUrl[2]; }
else if (/^https?:\/\//.test(src)) {
  const res = await this.helpers.httpRequest({ url: src, encoding: 'arraybuffer', returnFullResponse: true });
  mime = String(res.headers['content-type'] || mime).split(';')[0];
  b64 = Buffer.from(res.body).toString('base64');
} else { b64 = src; }
const ext = mime.split('/')[1] === 'jpeg' ? 'jpg' : (mime.split('/')[1] || 'png');
return [{ json: { b64, mime, ext } }];

